<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,computed} from 'vue'
import {RouterLink,useRouter} from 'vue-router'
import {api,ApiError,date,type Staff} from '../api'
import {pending} from '../commands'
import {readMonitoring,type Snapshot} from '../monitoring'
const router=useRouter(),staff=ref<Staff|null>(null),snapshot=ref<Snapshot|null>(null),loading=ref(false),error=ref(''),elapsed=ref(0),ageAtReceipt=ref(0)
let generation=0,disposed=false,received=performance.now();const timer=setInterval(()=>{elapsed.value=performance.now()-received},1000)
const old=computed(()=>!snapshot.value||loading.value||!!error.value||ageAtReceipt.value+elapsed.value>=snapshot.value.staleSeconds*1000)
const dependency=(s:string)=>({UP:'探測成功',UNAVAILABLE:'無法核對',MISSING:'設定佇列不存在',DISABLED:'能力關閉，未探測',NOT_CHECKED:'監控關閉，未探測'}[s]||s)
const labels:Record<string,string>={purchaseProcessing:'購票請求 PROCESSING',outboxUnpublished:'Outbox 尚未確認發布',outboxExpiredLeases:'Outbox 租約已過期',outboxUnknown:'Outbox 未知發布結果',gateREADY:'庫存 gate READY',gateCLOSED:'庫存 gate CLOSED',gateDIRTY:'庫存 gate DIRTY',stockWAITING:'預扣恢復 WAITING',stockLEASED:'預扣恢復 LEASED',stockREVIEW:'預扣恢復 REVIEW',returnWAITING:'返還恢復 WAITING',returnLEASED:'返還恢復 LEASED',returnREVIEW:'返還恢復 REVIEW',stockExpiredLeases:'預扣恢復逾期租約',returnExpiredLeases:'返還恢復逾期租約',stockExhaustedReview:'預扣預算耗盡 REVIEW',returnExhaustedReview:'返還預算耗盡 REVIEW',policyACTIVE:'來源授權 ACTIVE',policyEXHAUSTED:'來源授權 EXHAUSTED',policySTOPPED:'來源授權 STOPPED',discoveredEnrolled:'已登記返還來源',discoveredExisting:'已有返還操作來源'}
async function load(){const g=++generation,started=performance.now();loading.value=true;error.value='';try{const s=await readMonitoring();if(!disposed&&g===generation){snapshot.value=s;received=performance.now();ageAtReceipt.value=Math.max(s.durationMs,received-started);elapsed.value=0}}catch(e){if(!disposed&&g===generation){error.value=(e as Error).message;if(e instanceof ApiError&&e.status===401)await router.push('/staff/login')}}finally{if(g===generation)loading.value=false}}
onMounted(async()=>{try{staff.value=await api('/auth/me');await load()}catch{await router.push('/staff/login')}})
onBeforeUnmount(()=>{disposed=true;generation++;clearInterval(timer)})
</script>
<template><section v-if="staff" class="content admin-page"><RouterLink to="/staff" class="back-link">← 活動管理</RouterLink><div class="section-heading"><div><div class="eyebrow">RUNTIME OBSERVATIONS</div><h1>執行監控</h1><p>{{staff.username}} · 唯讀監控，不修改票額或工作</p></div><button :disabled="loading" @click="load">重讀監控快照</button></div><p v-if="pending" class="notice warning">有原員工操作尚未確認，原內容保留；監控讀取不會解除或重送。</p><p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="old&&snapshot" class="notice warning" role="status">舊快照／尚未重新查證，不能當成目前健康。</p><p class="notice">心跳只代表最近回報，不證明每個工作正常。MQ待投遞量不含已送出未ACK訊息；旗標開啟不表示程序存活。</p><template v-if="snapshot"><p>快照時間 {{date(snapshot.postgres.observedAt)}} · 此回覆角色 {{snapshot.localRole}} · {{snapshot.staleSeconds}} 秒後需重新核對</p><p v-if="!snapshot.enabled" class="notice" role="status">監控目前關閉，不顯示健康或空積壓的推測。</p><template v-else><section class="panel" aria-label="程序心跳"><h2>程序心跳</h2><article v-for="r in snapshot.postgres.roles" :key="r.role" :data-role="r.role"><h3>{{r.role}}</h3><p>預期 {{r.expected}} · 最近回報 {{r.recent}} · 過期紀錄 {{r.stale}}</p><p v-if="!old&&r.recent<r.expected" class="notice warning">最近回報不足，需核對實際程序。</p><p class="muted">最近回報中的運行監聽器 {{r.recentConsumerLifecycles}}；不代表已連線，實際 broker consumers 請看下方。</p></article></section><section class="panel" aria-label="依賴探測"><h2>依賴探測</h2><p>PG：聚合快照已讀取 · Redis：{{dependency(snapshot.redis)}} · MQ：{{dependency(snapshot.broker.state)}}</p><p v-for="(q,name) in snapshot.broker.queues" :key="name">{{name}} · 待投遞 {{q.ready}} · consumers {{q.consumers}}</p><p class="muted">探測取樣時間不同，沒有跨 PG／Redis／MQ 的原子健康快照。</p></section><section class="panel" aria-label="持久積壓與庫存gate"><h2>持久積壓與庫存 gate</h2><p v-for="(value,key) in snapshot.postgres.counts" :key="key">{{labels[key]||key}} · {{value}}</p><p class="muted">REVIEW或逾期租約不會因監控而補做／重開預算；請到原操作頁核對。</p></section></template><details class="panel"><summary>此回覆節點的能力旗標</summary><p v-for="(v,k) in snapshot.capabilities" :key="k">{{k}} · {{v?'已配置開啟':'關閉'}}</p><p>這些是此節點設定，不是其他節點健康或能力一致性的證明。</p></details></template></section></template>
